import {CAMERA_PLANS,CAMERA_CASES,CAMERA_BUSINESSES,cameraExperiment,cameraPosition} from './camera.mjs';
import {AB_AUDIENCES,AB_PRESETS,AB_BUSINESSES,calculateAB} from './ab.mjs';
import {INDUSTRIES,CUSTOMERS,createState,isStateValid,totals,addItem,checkout,nextStep,cancelOrder,metrics,log} from './core.mjs';
const $=s=>document.querySelector(s);
const KEY='flowdesk-industry-lab-v1';
let state=createState(),storageOK=true;
try{const old=JSON.parse(localStorage.getItem(KEY));if(isStateValid(old))state=old;}catch{storageOK=false;}
let category='ทั้งหมด',search='',segment=0,previewText='',toastTimer;
const fmt=n=>new Intl.NumberFormat('th-TH',{maximumFractionDigits:2}).format(n);
const money=n=>'฿'+fmt(n);
const time=t=>new Date(t).toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit'});
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const domain=()=>state.domains[state.industry];const config=()=>INDUSTRIES[state.industry];
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',bowl:'M3 10h18c0 6-4 9-9 9s-9-3-9-9Z M7 5v2 M12 3v4 M17 5v2 M7 21h10',bag:'M5 7h14l2 14H3L5 7Z M8 8V6a4 4 0 0 1 8 0v2',spark:'m12 3 2.3 6.7L21 12l-6.7 2.3L12 21l-2.3-6.7L3 12l6.7-2.3L12 3Z',factory:'M3 21V9l6 4V7l6 4V3h4v18H3Z M7 17h1 M12 17h1 M17 17h1',clipboard:'M9 4H5v17h14V4h-4 M9 2h6v5H9z M8 12l2 2 5-5 M8 18h7',chart:'M4 3v18h17 M8 16v-4 M13 16V7 M18 16V4',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.9 M16 3.1a4 4 0 0 1 0 7.8',link:'M10 13a5 5 0 0 0 7 .1l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7-.1l-3 3a5 5 0 0 0 7 7l2-2',download:'M12 3v12 m-5-5 5 5 5-5 M4 15v6h16v-6',refresh:'M20 7V3l-4 4 M20 7a8 8 0 1 0 0 10',search:'m21 21-6-6 M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14',close:'m6 6 12 12 M18 6 6 18',arrow:'M5 12h14 m-5-5 5 5-5 5',receipt:'M6 3h12v18l-3-2-3 2-3-2-3 2V3Z M9 7h6 M9 11h6 M9 15h3',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',check:'m5 12 4 4L20 5',box:'m3 7 9-4 9 4v10l-9 4-9-4V7Z m0 0 9 5 9-5 M12 12v9',wallet:'M3 6h16v15H3V6Z M3 6V3h13v3 M16 11h5v5h-5v-5Z',info:'M12 11v6 M12 7h.01 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',mail:'M3 5h18v14H3V5Z m0 0 9 8 9-8'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`;}
