 coffee:'<ellipse cx="50" cy="75" rx="23" ry="5" fill="#c9c0b3"/><path d="m29 25 7 48h30l7-48Z" fill="#a18d74"/><path d="m32 42 4 31h30l4-31Z" fill="#5c4e3e"/><path d="m33 29 7-1 3 9-7 1Zm18 3 10-3 3 9-10 2Z" fill="#d2d1be" opacity=".75"/><ellipse cx="51" cy="25" rx="22" ry="5" fill="#66543d"/><path d="m56 25 4-21" stroke="#e7e3d7" stroke-width="4"/>',
