 tote:'<path d="m25 30 52 2 5 42H20Z" fill="#c9b58d"/><path d="M36 32V20c0-17 27-15 27 1v12" fill="none" stroke="#99835e" stroke-width="5"/><path d="M27 35h48l3 35H24Z" fill="#deceb1"/><path d="M41 46h18v15H41Z" fill="#829378"/><path d="m44 51 4 4 8-7" fill="none" stroke="#e1e7ce" stroke-width="2"/>',
