 car:'<path d="m20 41 11-19h36l13 19 6 5v21H15V47Z" fill="#8da4a1"/><path d="m33 26-7 15h47l-9-15Z" fill="#dce5de"/><path d="M17 51h66v14H17Z" fill="#a9bbb2"/><circle cx="28" cy="67" r="8" fill="#4a5f58"/><circle cx="73" cy="67" r="8" fill="#4a5f58"/><path d="M24 51h10m32 0h10" stroke="#eee7bd" stroke-width="4"/>',
 clean:'<path d="M33 27h31l6 45H27Z" fill="#9dac96"/><path d="M40 15h21v13H40Z" fill="#526a58"/><path d="m47 16 12-8 18 5v7H59" fill="#b6c5a7"/><path d="M34 43h30v19H34Z" fill="#e4e9d5"/><path d="m44 48 4 9 8-9" fill="none" stroke="#a2b58f" stroke-width="2"/>',
