const PROFILE_META={
 demo01:{role:'พนักงานบัญชี',need:'มีเวลารอไม่เกิน 10 นาที',source:'แบบสอบถามสมาชิก 28 ต.ค. 2026',relation:'แนะนำคุณต้นด้วยรหัส REF-DEMO-01',consent:'อนุญาต LINE จำลอง · 28 ต.ค. 2026'},
 demo02:{role:null,need:'ต้องการทราบราคาและเวลาส่งมอบก่อนตัดสินใจ',source:'สัมภาษณ์ตัวอย่าง 30 ต.ค. 2026',relation:'เข้าร่วมผ่านรหัส REF-DEMO-01 ของคุณมิน',consent:'อนุญาตอีเมลจำลอง · 30 ต.ค. 2026'},
 demo03:{role:'นักออกแบบอิสระ',need:'ต้องการตัวเลือกและราคาที่ชัดเจนโดยไม่ต้องรับข่าวสาร',source:'แบบสอบถามหลังบริการ 1 พ.ย. 2026',relation:null,consent:'ไม่อนุญาตการตลาด · 1 พ.ย. 2026'},
 walkin:{role:null,need:null,source:null,relation:null,consent:'ไม่มีบัญชีสมาชิกหรือสิทธิ์การตลาด'}
};
